def sidConfigRest(session_id, method="GET", parName="lsuip", parValue="", host=socketAddress, port=socketPort, restVer=""):
    """get/set given SID configuration parameters (one parameter at time)

    :param session_id: session identificator of the current test session
    :param method: GET | POST, GET get value, POST set value.
    :param parName: requested parameter, possible parameters are:
                    "tstmip": test manager Ip address
                    "lsuip" : LSU Ip address
                    "ipmi"  : LSU Ip address for IPMI
                    "perspective": sid perspective
                    "stack": TODO !
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS

    :return: if method is GET:
             {"result": result, "error": error, "parameter": ""}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description otherwise is empty
             *parameter* is the value of the requested parameter
             if method is POST:
             {"result": result,"error": error}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description

    :example: sidConfig("c601922d-cb8a-4ef2-b515-c9934c3d606e",
                        method="GET",
                        parName="lsuip",
                        parValue="",
                        host="192.168.1.10",
                        port="8090")
    :example: sidConfig("c601922d-cb8a-4ef2-b515-c9934c3d606e",
                        method="POST",
                        parName="lsuip",
                        parValue="10.10.0.88",
                        host="192.168.1.10",
                        port="8090")

    :sample GET output: {u'parameter': u'172.17.12.140',
                         u'result': u'success',
                         u'error': u''}
    :sample POST output: {u'result': u'success', u'error': u''}
    """
    cmd = "/harness/lsuConfiguration/%s" % (session_id)
    payload = {}
    data = json.dumps(payload).encode("utf-8")
    if method == "GET":
        cmd += "?parName=%s" % (parName)
    elif method == "POST":
        cmd += "?parName=%s&value=%s" % (parName, parValue)
    else:
        res = {"result": "failed", "error": "unknown method " + method}
    req = Request("http://%s:%s%s" % (host, port, cmd), data=data, headers=headers)
    try:
        req.get_method = lambda: method
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.testSession():  AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err, "sessionId": ""}
    return res


def getApiRestVersion(host=socketAddress, port=socketPort):
    """
    get API version

    :param session_id: session identificator of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening

    :return: {"version": <version>,
              "error": "",
              "result": ""}

    :example: getApiRestVersion("c601922d-cb8a-4ef2-b515-c9934c3d606e", host=harnessIp, port=harnessPort)

    :sample output: {u'version': u'1.0.0', u'result': u'success', u'error': u''}
    :sample output: error (on windows OS) in case of unreachable IP: 
        {'result': 'failed',
         'error': (URLError,socket.timeout)(TimeoutError(
                            10060,
                            'A connection attempt failed because the connected party
                                did not properly respond after a period of time,
                                or established connection failed because connected
                                host has failed to respond',
                            None,
                            10060,
                            None)),
         'version': ''}

    :sample output: error (on windows OS) in case of reacable IP but unexisting port: 
        {'result': 'failed',
         'error': (URLError,socket.timeout)(ConnectionRefusedError(
                            10061,
                            'No connection could be made because the target machine actively refused it',
                            None,
                            10061,
                            None)),
         'version': ''}

    :sample: error in case of old version not implementing the request:
        {'result': 'failed',
         'error': <HTTPError 405: 'HTTP method GET is not supported by this URL'>,
         'version': ''}
    """
    cmd = "/harness/version/"
    payload = {}
    data = json.dumps(payload).encode("utf-8")
    method = "GET"
    req = Request("http://%s:%s%s" % (host, port, cmd), data=data, headers=headers)
    try:
        req.get_method = lambda: method
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
    except HTTPError as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getApiRestVersion(): AirMosaic gave error (ip={0}, err={1})"
               .format(host, str(pe_err)))
        res = {"result": "success", "error": "", "version": "0.0.0"}
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getApiRestVersion(): AirMosaic not running on {0}:{1}, err={2}"
               .format(host, port, str(pe_err)))
        res = {"result": "failed", "error": pe_err, "version": ""}
    except Exception as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getAirmosaicStatus():  AirMosaic connection problem: ip={0}, err={1} type={2}"
               .format(host, str(pe_err, str(type(pe_err).__name__))))
