def testSession(host=socketAddress, port=socketPort, method="POST", session_id="", restVer=""):
    """Opens a new test session, or closes an open one.
       (Open connection to Airmosaic and assing a new session Id, and disconnect from Airmosaic)

    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param method: POST | DELETE, POST opens a new test session, DELETE closes an open session
    :param restVer: API REST version to use for future request to HARNESS

    :return: if method is POST:
             {"result": result, "error": error, "sessionId": sessionId}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description
             *sessionId* is the sessionId created
             if method is GET:
             {"result": result,"error": error}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description

    :example: testSession(host=harnessIp, port=harnessPort, method="POST", session_id="")
    :example: testSession(host=harnessIp, port=harnessPort, method="DELETE", session_id=sesId)

    :sample output: {u'message': u'{"result":"success",
                                    "sessionId":"c601922d-cb8a-4ef2-b515-c9934c3d606e",
                                    "error":""}',
                     u'type': u'ok'}   # TO DO it will change soon !
    :sample output: {u'message': u'{"result":"success","error":""}', u'type': u'ok'} # TO DO it will change soon !
    """
    cmd = "/harness/testSession"
    payload = {}
    data = json.dumps(payload).encode("utf-8")
    if method == "DELETE":
        cmd += "/%s" % session_id
    req = Request("http://%s:%s%s" % (host, port, cmd), data=data, headers=headers)
    try:
        req.get_method = lambda: method
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.testSession():  AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err, "sessionId": ""}
    return res


