def loadAirmosaicFile(session_id, filename, host=socketAddress, port=socketPort, restVer=""):
    """Load a scenario or a sid file to AirMosaic.

    :param sessionId: session_id of the current test session
    :param filename: path to a sid or sce Airmosaic file
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.

    :return: {"result": result,"error": error}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description

    :example: loadAirmosaicFile("d33039df-a3af-464a-8c7b-77749a403063", "mytest.sid", "192.168.1.10", "8090")

    :sample output: {"result": "success","error": ""}
    """
    if filename.rsplit(".")[-1] == "sid":
        cmd = "/harness/sid/%s?sidName=%s" % (session_id, filename)
    elif filename.rsplit(".")[-1] == "sce":
        cmd = "/harness/scenario/%s?scenarioFilename=%s" % (session_id, filename)
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    try:
        req.get_method = lambda: "PUT"
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [], "*DEBUG* pymosaicRest.loadAirmosaicFile():  AirMosaic connection problem: " +
               filename + ": ip={0}, err={1}".format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    return res


