def getResult(session_id, filename="", host=socketAddress, port=socketPort, restVer=""):
    """Retrieve the test result in XML format after the test termination.

    :param sessionId: session_id of the current test session
    :param filename: path to a file where XML stream of test result would be written
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.

    :return: {"result": result, "error": error}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description

    :example: getResult("d33039df-a3af-464a-8c7b-77749a403063", 'Result.xml' "192.168.1.10", "8090")

    :sample output: {"result": "failed","error": "Errno 111 Connection refused"}
    """
    cmd = "/harness/testResult/%s" % (session_id)
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    try:
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))#["message"]
        #pe_log(False, [], "*DEBUG* pymosaicRest.getResult(): res = {0}".format(res))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getResult():  AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    if res["result"] == "success" and filename:
        try:
            outfile = open(filename, 'wt')
            outfile.write(res['testResult'])
            outfile.close()
            res['testResult'] = filename
        except (URLError,socket.timeout) as pe_err:
            pe_log(False, [],
                   "*DEBUG* pymosaicRest.getResult(): cannot write XML file: ip={0}, err={1}".format(host, str(pe_err)))
            res['error'] = 'Cannot save test result to %s: %s' % (filename, pe_err)
            res['result'] = 'failed'
    return res


