def amOptions(session_id, enableAMM="", clockTimer="", host=socketAddress, port=socketPort, restVer=""):
    """Set one or more airmosaic options.

    :param sessionId: session_id of the current test session
    :param enableAMM: true | false
    :param clockTimer: clockTimer expressed in ms
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.

    :return: {"result": result,"error": error}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description

    :example: options("d33039df-a3af-464a-8c7b-77749a403063",
                      enableAMM="false", clockTimer="300000", "192.168.1.10", "8090")

    :sample output: {"result": "failed","error": "Errno 111 Connection refused"}
    """
    if enableAMM:
        if not (enableAMM == "false" or enableAMM == 'true'):
            return {"result": "failed", "error": "{0} : invalid value for enableAMM.".format(enableAMM)}

    if enableAMM and clockTimer:
        cmd = "/harness/options/%s?enableAMM=%s&clockTimer=%s" % (session_id, enableAMM, clockTimer)
    elif enableAMM and not clockTimer:
        cmd = "/harness/options/%s?enableAMM=%s" % (session_id, enableAMM)
    elif not enableAMM and clockTimer:
        cmd = "/harness/options/%s?clockTimer=%s" % (session_id, clockTimer)
    elif not enableAMM and not clockTimer:
        return {"result": "failed", "error": "{1} : missing option values for enableAMM"}        
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    try:
        req.get_method = lambda: "PUT"
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))#["message"]
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.options():  AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    return res


