def scenarioLogger(session_id, startId="", endId="", host=socketAddress, port=socketPort, restVer=""):
    """Retrieve scenario logger messages.

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.
    :param startId: starting line number in the scenario logger to be reported,
                    if obmitted all the line from the beginning are collected
    :param endId: finish line number in the scenario logger to be reported,
                  if obmitted all the line untill the end are collected

    :return: {"result": result, "error": error, logRecords: [.]},
            where \n
            *result* can be *success* or *failed*, \n
            *error* is the failure cause, \n
            *logRecords* is an array of structure defined as:\n
            {'recordId': record,
             'datetime': datetime,
             'instance': instance,
             'messageLevel': messageLevel,
             'category': category,
             'message': message,
             'group': group
            }
            messegeLevel can be one of the following:  "ERROR", "WARNING", "INFORMATION", "DEBUG", "UNKNOWN"

    :example: scenarioLogger("d33039df-a3af-464a-8c7b-77749a403063", startId="", endId="", "192.168.1.10", "8090")

    :sample output:
    """
    cmd = "/harness/scenarioLogger/%s?startId=%s&endId=%s" % (session_id, startId, endId)
    """
    if startId and endId:
        cmd = "/harness/scenarioLogger/%s?startId=%s&endId=%s" % (session_id, startId, endId)
    elif startId and not endId:
        cmd = "/harness/scenarioLogger/%s?startId=%s" % (session_id, startId)
    elif not startId and endId:
        cmd = "/harness/scenarioLogger/%s?endId=%s" % (session_id, endId)
    elif not startId and not endId:
        cmd = "/harness/scenarioLogger/%s" % (session_id)
    """
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    try:
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))#["message"]
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.scenarioLogger():  AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    return res


def bugreport(session_id, filename="", host=socketAddress, port=socketPort, restVer=""):
    """Collect airmosaic and testmanager logs.

    :param sessionId: session_id of the current test session
    :param filename: path to a file where stream of test result would be written
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.

    :return: {"result": result,"error": error, "bugreportFile": <report file name>}, where
             *result* can be *success* or *failed*
             *error* is the failure cause description
             *bugreportFile* is the base64 encoded bugreport, if filename exists return saved filename.

    :example: bugreport("d33039df-a3af-464a-8c7b-77749a403063", "c:\\tmp\\bugreport.zip", "192.168.1.10", "8090")

    :sample output: {"result": "failed","error": "Errno 111 Connection refused"}
    """
    cmd = "/harness/bugreport/%s" % (session_id)
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    res = {}
    try:
        #pe_log(False, [], "cmd ={0}".format(cmd))
        open2 = urlopen(req, timeout=6*URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
        #pe_log(False, [], "*DEBUG* pymosaicRest.bugreport(): step1 res ={0}".format(res.keys()))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.bugreport(): AirMosaic connection problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    #pe_log(False, [], "*DEBUG* pymosaicRest.bugreport(): res ={0}".format(res.keys()))
    if res["result"] == "success" and filename:
        try:
            outfile = open(filename, 'wb')
            outfile.write(base64.b64decode(res['bugreportFile']))
            outfile.close()
            res['bugreportFile'] = filename
        except (URLError,socket.timeout) as pe_err:
            pe_log(False, [],
                   "*DEBUG* pymosaicRest.bugreport(): cannot save file, error="+str(pe_err))
            res['error'] = 'Error cannot save file %s: %s' % (filename, pe_err)
            res['result'] = 'failed'
    return res


