def getAirmosaicStatus(session_id, host=socketAddress, port=socketPort, restVer=""):
    """Retrieve the airmosaic status.

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to use for future request to HARNESS, currently not user.

    :return: {"result": result, "error": error, "status": }, where
             *result* can be *success* or *failed*
             *error* is the failure cause description
             *status* is the AirMosaic status, which can be one of the following values:
                SIMINIT_AVAILABLE_INVALID   A sid file is available, but it is invalid, no simulation can be started
                SIMINIT_AVAILABLE           One sid file has been loaded and the simulator can be initialized
                RUNNING_SIMINIT             The sim init file has been loaded and the initialization is taking place
                RUNNING_SIMINIT_SCEAVAIL    The sim init file has been loaded and the initialization is taking place
                                            and scenario is already loaded
                SIMINIT_COMPLETED           The simulator initialization has been completed, now a scenario can be run
                SCENARIO_AVAILABLE          A scenario has been successfully loaded
                SCENARIO_RUNNABLE           A scenario has been successfully loaded and init is completed
                RUNNING_SCENARIO            A test sequence is running
                SCENARIO_COMPLETED          The test sequence has been completed
                ABNORMAL_FAIL               The test sequence has failed while running due to an error (e.g. Tstm crash)
                SID_OPENING                 Opening of a SID file
                PLAY_SIMINIT_AVAIL          Play a log file while a SID file has been opened
                PLAY_SCEN_AVAIL             Play a log file while a SID file and a SCE file have been opened
                NONE

    :example: getAirmosaicStatus("d33039df-a3af-464a-8c7b-77749a403063", "192.168.1.10", "8090")

    :sample output: {"result":"success","error":"","status":"RUNNING_SCENARIO"}
    """
    cmd = "/harness/airMosaic/%s" % (session_id)
    req = Request("http://%s:%s%s" % (host, port, cmd), headers=headers)
    try:
        open2 = urlopen(req, timeout=URLOPEN_TIMEOUT)
        res = json.loads(open2.read().decode("utf-8"))
    except (URLError,socket.timeout) as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getAirmosaicStatus():  AirMosaic connection URL problem: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {"result": "failed", "error": pe_err}
    except TimeoutError as pe_err:
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getAirmosaicStatus():  AirMosaic connection timeout: ip={0}, err={1}"
               .format(host, str(pe_err)))
        res = {'result': 'failed', 'status': '', 'error': pe_err}
    except exception as pe_err:
        pe_log(json_output, json_buffer,
               "*DEBUG* pymosaicRest.getAirmosaicStatus(): complete stack:\n{0}".format(traceback.format_exc()))
        pe_log(False, [],
               "*DEBUG* pymosaicRest.getAirmosaicStatus():  AirMosaic connection problem: ip={0}, err={1} type={2}"
               .format(host, str(pe_err, str(type(pe_err).__name__))))
        res = {'result': 'failed', 'status': '', 'error': pe_err}
    return res


